const DEFAULT_DIARY_TEXT_STYLE = { size: "base", color: "default", bold: false, bg: "none" };

const DIARY_STYLE_HEX_COLOR = {
  default: "#44403C",
  rose: "#E11D48",
  sky: "#2383E2",
  emerald: "#047857",
  amber: "#B45309",
  violet: "#6D28D9",
  muted: "#A8A29E"
};

const DIARY_STYLE_HEX_BG = {
  none: "",
  amber: "#FEF3C7",
  emerald: "#D1FAE5",
  sky: "#E0F2FE",
  rose: "#FFE4E6"
};

const getDiaryTextStyleClasses = (ts) => {
  const s = ts || DEFAULT_DIARY_TEXT_STYLE;
  const sizeCls = (PAGE_TEXT_SIZES.find((x) => x.id === s.size) || PAGE_TEXT_SIZES[1]).cls;
  const colorCls = (PAGE_TEXT_COLORS.find((x) => x.id === s.color) || PAGE_TEXT_COLORS[0]).cls;
  const bgCls = (PAGE_TEXT_BG_COLORS.find((x) => x.id === s.bg) || PAGE_TEXT_BG_COLORS[0]).cls;
  return `${sizeCls} ${colorCls} ${s.bold ? "font-bold" : ""} ${bgCls}`.trim();
};

const isDiaryTextStyleCustom = (ts) => {
  if (!ts) return false;
  return (
    (ts.size && ts.size !== "base") ||
    (ts.color && ts.color !== "default") ||
    Boolean(ts.bold) ||
    (ts.bg && ts.bg !== "none")
  );
};

const DIARY_SIZE_PX = { sm: "12.5px", base: "14.5px", lg: "17px", xl: "20px" };

const plainTextToDiaryHtml = (txt) =>
  String(txt || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\n/g, "<br>");

const sanitizeDiaryHtml = (rawHtml) => {
  const str = String(rawHtml || "");
  if (!str) return "";
  if (typeof DOMParser === "undefined") return plainTextToDiaryHtml(str.replace(/<[^>]+>/g, ""));
  try {
    const doc = new DOMParser().parseFromString(`<div>${str}</div>`, "text/html");
    const root = doc.body.firstChild;
    const ALLOWED_TAGS = new Set(["SPAN", "BR", "DIV", "P", "B", "STRONG", "I", "EM"]);
    const walk = (node) => {
      if (node.nodeType === 3) {
        return node.textContent
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;");
      }
      if (node.nodeType !== 1) return "";
      const tag = node.tagName.toUpperCase();
      if (tag === "BR") return "<br>";
      const inner = Array.from(node.childNodes).map(walk).join("");
      if (!ALLOWED_TAGS.has(tag)) return inner;
      if (tag === "SPAN") {
        const st = node.style;
        const safeParts = [];
        if (st.fontSize && /^\d+(\.\d+)?px$/.test(st.fontSize)) safeParts.push(`font-size:${st.fontSize}`);
        if (st.color) safeParts.push(`color:${st.color}`);
        if (st.backgroundColor) safeParts.push(`background-color:${st.backgroundColor}`);
        if (st.fontWeight) safeParts.push(`font-weight:${st.fontWeight}`);
        if (st.padding) safeParts.push(`padding:${st.padding}`);
        if (st.borderRadius) safeParts.push(`border-radius:${st.borderRadius}`);
        return safeParts.length > 0 ? `<span style="${safeParts.join(";")}">${inner}</span>` : inner;
      }
      if (tag === "B" || tag === "STRONG") return `<strong>${inner}</strong>`;
      if (tag === "I" || tag === "EM") return `<em>${inner}</em>`;
      return `<div>${inner}</div>`;
    };
    return Array.from(root.childNodes).map(walk).join("");
  } catch (e) {
    return plainTextToDiaryHtml(str.replace(/<[^>]+>/g, ""));
  }
};

const parseCoordsFromMapUrl = (rawUrl) => {
  const s = String(rawUrl || "").trim();
  if (!s) return null;
  // Google Maps @lat,lng or q=lat,lng or !3dlat!4dlng
  const m1 = s.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (m1) return { lat: Number(m1[1]), lng: Number(m1[2]) };
  const m2 = s.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);
  if (m2) return { lat: Number(m2[1]), lng: Number(m2[2]) };
  const m3 = s.match(/[?&](?:q|query|ll)=(-?\d+\.\d+),(-?\d+\.\d+)/);
  if (m3) return { lat: Number(m3[1]), lng: Number(m3[2]) };
  return null;
};

const getNaverMapUrl = (item) => {
  const saved = String(item?.mapUrl || "").trim();
  if (saved && (saved.includes("naver.com") || saved.includes("naver.me"))) return saved;
  const q = encodeURIComponent(String(item?.placeName || item?.title || "").trim());
  return `https://map.naver.com/p/search/${q}`;
};

const getGoogleMapUrl = (item) => {
  const saved = String(item?.mapUrl || "").trim();
  if (saved && (saved.includes("google.com/maps") || saved.includes("goo.gl/maps") || saved.includes("maps.app.goo.gl"))) {
    return saved;
  }
  if (Number.isFinite(Number(item?.lat)) && Number.isFinite(Number(item?.lng)) && Number(item?.lat) !== 0) {
    return `https://www.google.com/maps/search/?api=1&query=${Number(item.lat)},${Number(item.lng)}`;
  }
  const q = encodeURIComponent(String(item?.placeName || item?.title || "").trim());
  return `https://www.google.com/maps/search/?api=1&query=${q}`;
};

let leafletLoadPromise = null;
const ensureLeafletLoaded = () => {
  if (typeof window === "undefined") return Promise.reject(new Error("no window"));
  if (window.L) return Promise.resolve(window.L);
  if (leafletLoadPromise) return leafletLoadPromise;
  leafletLoadPromise = new Promise((resolve, reject) => {
    if (!document.querySelector('link[data-leaflet-css="1"]')) {
      const link = document.createElement("link");
      link.rel = "stylesheet";
      link.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
      link.setAttribute("data-leaflet-css", "1");
      document.head.appendChild(link);
    }
    const script = document.createElement("script");
    script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    script.async = true;
    script.onload = () => (window.L ? resolve(window.L) : reject(new Error("Leaflet failed")));
    script.onerror = () => reject(new Error("Leaflet CDN load error"));
    document.head.appendChild(script);
  });
  return leafletLoadPromise;
};

