        pass: (() => {
          const parsed = parseQuickShoppingTextLocal("양파 1망, 부침두부 2모 사와");
          return parsed.length === 2 && parsed[0].name === "양파" && parsed[0].quantity === "1망" && parsed[1].name === "부침두부" && parsed[1].quantity === "2모";
        })()
