  const handleDiaryPhotoSelect = async (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    try {
      const curCount = Array.isArray(diaryForm.photos) ? diaryForm.photos.length : 0;
      const remain = Math.max(0, 4 - curCount);
      if (remain === 0) {
        showToast("📸 육아일기 사진은 최대 4장까지 첨부할 수 있습니다.");
        return;
      }
      const picked = files.slice(0, remain);
      const added = picked.map((file) => ({
        url: URL.createObjectURL(file),
        file
      }));
      setDiaryForm((prev) => {
        const curPhotos = Array.isArray(prev.photos) ? prev.photos : [];
        const nextPhotos = [...curPhotos, ...added].slice(0, 4);
        return {
          ...prev,
          photos: nextPhotos,
          photoUrl: nextPhotos[0]?.url || ""
        };
      });
      if (files.length > remain) {
        showToast(`📸 최대 4장 제한으로 ${picked.length}장만 첨부되었습니다.`);
      } else {
        showToast(`📸 사진 ${picked.length}장이 첨부되었습니다!`);
      }
    } catch (err) {
      showToast("⚠️ 사진 처리 중 오류가 발생했습니다.");
    } finally {
      if (diaryPhotoInputRef.current) diaryPhotoInputRef.current.value = "";
    }
  };


  const compressDiaryPhotoToBudget = async (file, maxChars = 650000) => {
    const presets = [
      { maxSide: 800, quality: 0.7 },
      { maxSide: 640, quality: 0.58 },
      { maxSide: 480, quality: 0.48 },
      { maxSide: 360, quality: 0.4 }
    ];
    let bestUrl = "";
    for (const p of presets) {
      const { previewUrl, base64, mimeType } = await fileToBase64(file, p);
      const dataUrl = previewUrl || (base64 ? `data:${mimeType || "image/jpeg"};base64,${base64}` : "");
      if (!dataUrl) continue;
      bestUrl = dataUrl;
      if (dataUrl.length <= maxChars) return dataUrl;
    }
    return bestUrl;
  };


  const handleSaveBabyDiary = async () => {
    if (!isAdminUnlocked) {
      showToast("🔒 육아일기는 관리자만 작성·열람할 수 있습니다.");
      return;
    }
    if (diaryUploadProgress) return;
    const formPhotos = Array.isArray(diaryForm.photos)
      ? diaryForm.photos
      : diaryForm.photoUrl
      ? [{ url: diaryForm.photoUrl, file: pendingDiaryPhotoFile }]
      : [];
    if (!diaryForm.content.trim() && !diaryForm.title.trim() && formPhotos.length === 0) {
      showToast("제목, 내용 또는 사진 중 하나 이상 입력해 주세요.");
      return;
    }
    if (!user || !db) {
      showToast("⚠️ 서버 연결 후 저장할 수 있습니다.");
      return;
    }
    const targetChildIds =
      Array.isArray(diaryForm.childIds) && diaryForm.childIds.length > 0
        ? diaryForm.childIds
        : [selectedChildId];
    const primaryChildLabel = targetChildIds.length >= 2 ? "시목·시율" : targetChildIds[0];
    const id = editingDiaryEntry ? editingDiaryEntry.id : `bd-${Date.now()}`;
    const cappedPhotos = formPhotos.slice(0, 4);
    const existingDataLen = cappedPhotos
      .filter((p) => !p?.file && p?.url && String(p.url).startsWith("data:"))
      .reduce((acc, p) => acc + String(p.url).length, 0);
    const newFilesCount = Math.max(1, cappedPhotos.filter((p) => p?.file).length);
    const perPhotoBudget = Math.max(90000, Math.floor((740000 - existingDataLen) / newFilesCount));
    setDiarySaveWarning("");
    const totalFilesToUpload = cappedPhotos.filter((p) => p?.file).length;
    let uploadedFileSeq = 0;
    setDiaryUploadProgress({
      stepText: totalFilesToUpload > 0 ? `🗜️ 고화질 자동 압축 중... (0/${totalFilesToUpload}장)` : "육아일기 저장 중...",
      pct: totalFilesToUpload > 0 ? 15 : 60
    });
    beginWrite();
    let ok = false;
    try {
      const finalUrls = [];
      for (let idx = 0; idx < cappedPhotos.length; idx++) {
        const pItem = cappedPhotos[idx];
        if (pItem?.file) {
          uploadedFileSeq += 1;
          setDiaryUploadProgress({
            stepText: `🗜️ 고화질 자동 압축 중... (${uploadedFileSeq}/${totalFilesToUpload}장)`,
            pct: Math.min(86, Math.round((uploadedFileSeq / totalFilesToUpload) * 75) + 10)
          });
          const compressedUrl = await compressDiaryPhotoToBudget(pItem.file, perPhotoBudget);
          if (compressedUrl) finalUrls.push(compressedUrl);
        } else if (pItem?.url && !pItem.url.startsWith("blob:")) {
          finalUrls.push(pItem.url);
        }
      }
      setDiaryUploadProgress({
        stepText: "서버에 일기 저장 중...",
        pct: 92
      });
      const payload = {
        id,
        childId: primaryChildLabel,
        childIds: targetChildIds,
        date: diaryForm.date || getTodayStr(),
        mood: diaryForm.mood || "😊 행복",
        title: (diaryForm.title || "").trim(),
        content: (diaryForm.content || "").trim(),
        contentHtml: sanitizeDiaryHtml(diaryForm.contentHtml || ""),
        textStyle: diaryForm.textStyle || { ...DEFAULT_DIARY_TEXT_STYLE },
        photoUrl: finalUrls[0] && String(finalUrls[0]).startsWith("http") ? finalUrls[0] : "",
        photoUrls: finalUrls,
        author: actorName || "관리자",
        createdAtMs: editingDiaryEntry?.createdAtMs || Date.now(),
        updatedAt: new Date().toISOString()
      };
      const saveResult = await Promise.race([
        setDoc(getDocRef("family_baby_diary_v8", id), payload).then(() => ({ timedOut: false })),
        new Promise((resolve) => setTimeout(() => resolve({ timedOut: true }), 6000))
      ]);
      setDiaryUploadProgress({
        stepText: saveResult?.timedOut ? "로컬 저장 완료 (백그라운드 동기화)" : "저장 완료!",
        pct: 100
      });
      setEditingDiaryEntry(null);
      setPendingDiaryPhotoFile(null);
      setDiaryForm({
        date: getTodayStr(),
        mood: "😊 행복",
        title: "",
        content: "",
        contentHtml: "",
        photoUrl: "",
        photos: [],
        childIds: [selectedChildId],
        textStyle: { ...DEFAULT_DIARY_TEXT_STYLE }
      });
      diarySavedRangeRef.current = null;
      setHasDiarySelection(false);
      setDiaryEditorSyncTick((t) => t + 1);
      recordActivity("육아", editingDiaryEntry ? "일기수정" : "일기등록", `${primaryChildLabel} · ${payload.date}`, {
        targetSubTab: "diary",
        targetId: id,
        targetChildId: targetChildIds[0] || selectedChildId
      });
      showToast(
        finalUrls.length > 0
          ? `📖 ${primaryChildLabel} 육아일기(사진 ${finalUrls.length}장 고화질 자동압축)가 저장되었습니다!`
          : `📖 ${primaryChildLabel} 육아일기가 저장되었습니다!`
      );
      ok = true;
    } catch (e) {
      const errDetail = e?.code ? `[${e.code}] ${e.message || ""}` : (e?.message || "용량 또는 네트워크 오류");
      setDiarySaveWarning(`❌ 육아일기 저장 실패 원인: ${errDetail}`);
      setSyncErrorMsg(`육아일기 저장 실패: ${errDetail}`);
      showToast(`❌ 육아일기 저장 실패: ${errDetail}`);
    } finally {
      setDiaryUploadProgress(null);
      endWrite(ok);
    }
  };


  const parseZipEntriesInBrowser = async (arrayBuffer) => {
    const bytes = new Uint8Array(arrayBuffer);
    const dv = new DataView(arrayBuffer);
    let eocdOffset = -1;
    for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) {
      if (dv.getUint32(i, true) === 0x06054b50) {
        eocdOffset = i;
        break;
      }
    }
    if (eocdOffset < 0) throw new Error("유효한 ZIP 파일이 아닙니다.");
    const totalEntries = dv.getUint16(eocdOffset + 10, true);
    let cdOffset = dv.getUint32(eocdOffset + 16, true);
    const decoder = new TextDecoder("utf-8");
    const filesMap = {};


    for (let idx = 0; idx < totalEntries; idx++) {
      if (dv.getUint32(cdOffset, true) !== 0x02014b50) break;
      const compMethod = dv.getUint16(cdOffset + 10, true);
      const compSize = dv.getUint32(cdOffset + 20, true);
      const nameLen = dv.getUint16(cdOffset + 28, true);
      const extraLen = dv.getUint16(cdOffset + 30, true);
      const commentLen = dv.getUint16(cdOffset + 32, true);
      const localHeaderOffset = dv.getUint32(cdOffset + 42, true);
      const fileName = decoder.decode(bytes.slice(cdOffset + 46, cdOffset + 46 + nameLen));
      cdOffset += 46 + nameLen + extraLen + commentLen;


      if (fileName.endsWith("/")) continue;
      if (dv.getUint32(localHeaderOffset, true) !== 0x04034b50) continue;
      const lhNameLen = dv.getUint16(localHeaderOffset + 26, true);
      const lhExtraLen = dv.getUint16(localHeaderOffset + 28, true);
      const dataStart = localHeaderOffset + 30 + lhNameLen + lhExtraLen;
      const compData = bytes.slice(dataStart, dataStart + compSize);


      let rawBytes = null;
      if (compMethod === 0) {
        rawBytes = compData;
      } else if (compMethod === 8 && typeof DecompressionStream !== "undefined") {
        const ds = new DecompressionStream("deflate-raw");
        const writer = ds.writable.getWriter();
        writer.write(compData);
        writer.close();
        const ab = await new Response(ds.readable).arrayBuffer();
        rawBytes = new Uint8Array(ab);
      }
      if (rawBytes) {
        filesMap[fileName] = rawBytes;
      }
    }
    return filesMap;
  };


  const handleImportBabyTimeZip = async (e) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (e.target) e.target.value = "";
    if (selectedFiles.length === 0) return;
    if (!isAdminUnlocked) {
      showToast("🔒 육아일기는 관리자만 가져올 수 있습니다.");
      return;
    }
    if (!user || !db) {
      showToast("⚠️ 서버 연결 후 가져올 수 있습니다.");
      return;
    }


    setDiaryUploadProgress({ stepText: `📦 일기 ZIP ${selectedFiles.length}개 분석 중...`, pct: 8 });
    beginWrite();
    let ok = false;
    try {
      const targetChild = zipTargetChildRef.current || selectedChildId || "시율";
      const seenGrowthKeys = new Set(
        babyGrowthLogs
          .filter((g) => g.childId === targetChild)
          .map((g) => `${g.date}|${g.weight ?? ""}|${g.height ?? ""}`)
      );
      const seenDiaryKeys = new Set(
        babyDiaryEntries
          .filter((d) => getDiaryEntryChildIds(d).includes(targetChild))
          .map((d) => `${d.date}|${String(d.content || "").trim()}`)
      );


      let importedDiaryCount = 0;
      let importedGrowthCount = 0;
      let skippedDupCount = 0;


      for (let fIdx = 0; fIdx < selectedFiles.length; fIdx++) {
        const file = selectedFiles[fIdx];
        const ab = await file.arrayBuffer();
        const filesMap = await parseZipEntriesInBrowser(ab);
        const txtKeys = Object.keys(filesMap).filter((k) => k.endsWith(".txt") && !k.toUpperCase().includes("NOTICE"));
        const ascKey = txtKeys.find((k) => k.includes("_asc")) || txtKeys[0];
        if (!ascKey) continue;


        const rawText = new TextDecoder("utf-8").decode(filesMap[ascKey]);
        const blocks = rawText.split(/={5,}/).map((b) => b.trim()).filter(Boolean);


      for (let bIdx = 0; bIdx < blocks.length; bIdx++) {
        const block = blocks[bIdx];
        const dateMatch = block.match(/date:\s*(\d{4}-\d{2}-\d{2})/i);
        if (!dateMatch) continue;
        const entryDate = dateMatch[1];


        const weightMatch = block.match(/weight:\s*([0-9.]+)/i);
        const heightMatch = block.match(/height:\s*([0-9.]+)/i);
        const headMatch = block.match(/head:\s*([0-9.]+)/i);


        let contentText = "";
        const contentIdx = block.search(/content:\s*/i);
        if (contentIdx >= 0) {
          let after = block.slice(contentIdx).replace(/^content:\s*/i, "");
          after = after.split(/\n(?:images:|weight:|height:|head:)/i)[0].trim();
          contentText = after;
        }


        const imageNames = [];
        const imgLineMatch = block.match(/images:\s*([^\n\r]+)/i);
        if (imgLineMatch) {
          imgLineMatch[1].split(",").forEach((seg) => {
            const clean = seg.replace(/images:\s*/i, "").trim();
            if (clean) imageNames.push(clean);
          });
        }


        setDiaryUploadProgress({
          stepText: `☁️ 파일 ${fIdx + 1}/${selectedFiles.length} 반영 중... (${bIdx + 1}/${blocks.length})`,
          pct: Math.min(92, Math.round((((fIdx + (bIdx + 1) / Math.max(1, blocks.length)) / selectedFiles.length)) * 82) + 10)
        });


        if (weightMatch || heightMatch || headMatch) {
          const wVal = weightMatch ? Number(weightMatch[1]) : null;
          const hVal = heightMatch ? Number(heightMatch[1]) : null;
          const hdVal = headMatch ? Number(headMatch[1]) : null;
          const gKey = `${entryDate}|${wVal ?? ""}|${hVal ?? ""}`;
          if (!seenGrowthKeys.has(gKey)) {
            seenGrowthKeys.add(gKey);
            const gId = `gr-bt-${targetChild}-${entryDate}-${Date.now()}-${fIdx}-${bIdx}`;
            const gPayload = {
              id: gId,
              childId: targetChild,
              date: entryDate,
              height: hVal,
              weight: wVal,
              head: hdVal,
              memo: "베이비타임 일기 가져오기"
            };
            await setDoc(getDocRef("family_baby_growth_v7", gId), gPayload);
            importedGrowthCount += 1;
          }
        }


        if (contentText || imageNames.length > 0) {
          const dKey = `${entryDate}|${contentText}`;
          if (seenDiaryKeys.has(dKey)) {
            skippedDupCount += 1;
            continue;
          }
          seenDiaryKeys.add(dKey);
          const cappedNames = imageNames.slice(0, 4);
          const perPhotoBudget = Math.max(90000, Math.floor(740000 / Math.max(1, cappedNames.length)));
          const finalUrls = [];
          for (const imgName of cappedNames) {
            const matchedKey = Object.keys(filesMap).find((k) => k === imgName || k.endsWith(`/${imgName}`));
            if (!matchedKey) continue;
            const ext = imgName.toLowerCase().endsWith(".png") ? "image/png" : "image/jpeg";
            const imgFile = new File([filesMap[matchedKey]], imgName, { type: ext });
            const compressedUrl = await compressDiaryPhotoToBudget(imgFile, perPhotoBudget);
            if (compressedUrl) finalUrls.push(compressedUrl);
          }
          const dId = `bd-bt-${entryDate}-${Date.now()}-${bIdx}`;
          const dPayload = {
            id: dId,
            childId: targetChild,
            childIds: [targetChild],
            date: entryDate,
            mood: "😊 행복",
            title: "",
            content: contentText,
            photoUrl: "",
            photoUrls: finalUrls,
            author: actorName || "관리자",
            createdAtMs: new Date(`${entryDate}T12:00:00`).getTime() || Date.now(),
            updatedAt: new Date().toISOString()
          };
          await setDoc(getDocRef("family_baby_diary_v8", dId), dPayload);
          importedDiaryCount += 1;
        }
      }
      }


      if (importedDiaryCount > 0 || importedGrowthCount > 0) {
        recordActivity("육아", "일기가져오기", `${targetChild} · 일기 ${importedDiaryCount}편 · 성장 ${importedGrowthCount}건`, {
          targetSubTab: "diary",
          targetChildId: targetChild
        });
      }
      setSelectedChildId(targetChild);
      showToast(
        `☁️ ${targetChild} 가져오기 완료! 일기 ${importedDiaryCount}편 · 성장 ${importedGrowthCount}건 클라우드 저장` +
          (skippedDupCount > 0 ? ` (중복 ${skippedDupCount}건 제외)` : "")
      );
      ok = true;
    } catch (err) {
      showToast(`❌ 일기 ZIP 가져오기 실패: ${err?.message || "형식 오류"}`);
    } finally {
      setDiaryUploadProgress(null);
      endWrite(ok);
    }
  };


  const computeActivitySummaryForChild = (childId) => {
    const list = babyActivities
      .filter((a) => a.childId === childId)
      .slice()
      .sort((a, b) => (Number(b.startMs) || 0) - (Number(a.startMs) || 0));
    const feeds = list.filter((a) => ["모유", "분유", "유축수유"].includes(a.type));
    const lastFeed = feeds[0] || null;
    const prevFeed = feeds[1] || null;
    const feedIntervalMs =
      lastFeed && prevFeed ? Math.max(0, (Number(lastFeed.startMs) || 0) - (Number(prevFeed.startMs) || 0)) : null;
    const lastDiaper = list.find((a) => a.type === "기저귀") || null;
    const lastSleep = list.find((a) => a.type === "수면") || null;
    return { list, lastFeed, prevFeed, feedIntervalMs, lastDiaper, lastSleep };
  };


