        const targetMealObj = todayMealsList.find((m) => m.slot === targetMealSlot) || todayMealsList[0];
        const isDinnerPending = curHrForMeal >= 15 && !todayMealsList.some((m) => m.slot === "저녁");
        const mealPreviewText = targetMealObj
